const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
function cohere(incomingFocus, outgoingFocus, stress, critical, secondaryMin, reducedMotion = false, reducedFlash = false) { const incoming = clamp01(incomingFocus), outgoing = clamp01(outgoingFocus), load = clamp01(stress), overlap = Math.min(incoming, outgoing), transfer = clamp01(overlap * (.68 + .32 * Math.max(incoming, outgoing))), motion = reducedMotion ? .97 : 1, flash = reducedFlash ? .97 : 1; const incomingScale = Math.max(.76, 1 - transfer * .16), outgoingScale = Math.max(.44, 1 - transfer * (critical ? .4 : .48)), secondaryScale = Math.max(secondaryMin, 1 - transfer * (critical ? .3 : .42) - load * .14) * motion * flash; return { transfer, incomingScale, outgoingScale, secondaryScale, primaryScale: 1, presentationOnly: true }; }
export function projectileFocusTransferCoherencePresentation(input, reducedMotion = false, reducedFlash = false) { return cohere(input.incomingFocus, input.outgoingFocus, input.stress, input.critical, .54, reducedMotion, reducedFlash); }
export function impactFocusTransferCoherencePresentation(input, reducedMotion = false, reducedFlash = false) { return cohere(input.incomingFocus, input.outgoingFocus, input.stress, input.critical, .46, reducedMotion, reducedFlash); }
export function hazardFocusTransferCoherencePresentation(input, reducedMotion = false, reducedFlash = false) { return cohere(input.incomingFocus, input.outgoingFocus, input.stress, input.critical, .44, reducedMotion, reducedFlash); }
export function safeLaneFocusTransferCoherencePresentation(input, reducedMotion = false, reducedFlash = false) { return cohere(input.incomingFocus, input.outgoingFocus, input.stress, input.critical, .52, reducedMotion, reducedFlash); }
export function specialistFocusTransferCoherencePresentation(input, reducedMotion = false, reducedFlash = false) { return cohere(input.incomingFocus, input.outgoingFocus, input.stress, input.critical, .48, reducedMotion, reducedFlash); }
export function focusTransferCoherenceBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), stress = clamp01(input.stress), overlap = Math.min(clamp01(input.incomingFocus), clamp01(input.outgoingFocus)), load = clamp01(stress * .7 + overlap * .22 + critical * .08); return { transfer: overlap, primaryScale: 1, secondaryScale: Math.max(.46, 1 - load * .46) * (reducedMotion ? .97 : 1) * (reducedFlash ? .97 : 1), presentationOnly: true }; }
